insert into academy_survey.forms (slug, def, status, sort) values
  ('sat-us-curriculum', $seed${"id": "sat-us-curriculum", "kicker": "미국교과 설명회 만족도 조사", "title": "미국교과 설명회 만족도 조사", "greeting": "Dear parents,", "intro": [], "thanks": "소중한 응답 감사합니다. 리딩브레인영어학원", "sections": [{"title": "설문", "items": [{"id": "g2129634414", "label": "[개인정보 수집.이용 동의]\n\n1. 수집하는 개인정보 항목 성명, 학년, 휴대폰번호 \n2. 개인정보의 수집 및 이용 목적 제공하신 정보는 학원 설명회 만족도 및 홍보를 위해 사용합니다. \n\n* 본인 확인 식별(동명이인 등)절차에 이용(성명, 학년, 휴대폰번호)\n* 의사소통 및 정보 전달, 홍보, 설명회 특전 전달 등에 이용(성명, 학년, 휴대폰번호)\n*개인정보의 보유 및 이용기간 수집된 개인정보의 보유 기간은 <만족도조사> 종료 후 1년간이며, 삭제 요청시, 당사자는 개인 정보를 재생이 불가능한 방법으로 즉시 파기합니다.", "required": true, "type": "single", "options": ["동의합니다.", "동의하지 않습니다."]}, {"id": "g2044212928", "label": "1. 자녀의 학교, 학년, 이름을 적어주세요. (예. 빛가온초 / 6학년 / 김소마)", "required": true, "type": "text", "short": true}, {"id": "g894446369", "label": "2. 현재 우리학생은 어느학원에 재원 중이거나 예정인지 선택해주세요.", "required": true, "type": "multi", "options": ["재원생", "비재원생"]}, {"id": "g1059996973", "label": "3. 학부모님 연락처를 남겨주세요.", "required": false, "type": "text", "short": true}, {"id": "g768785781", "label": "4. 오늘 설명회 만족도를 체크해주세요:)", "required": true, "type": "single", "options": ["매우만족", "만족", "보통", "부족", "매우부족"]}, {"id": "g113709817", "label": "5. 오늘 설명회에서 우리 자녀에게 바로 도움이 되었던 내용은 무엇일까요?", "required": true, "type": "text"}, {"id": "g2124757574", "label": "6. 학원에 바라는 점이 있다면 남겨주세요. 적극적으로 반영하겠습니다.", "required": true, "type": "text"}, {"id": "g2044700041", "label": "7. 학원에 상담을 원하신다면,  내용을 선택해주세요:)", "required": false, "type": "multi", "options": ["정규수업 커리큘럼", "비교과관리 진로적성 컨설팅", "그 외, 우리아이에게  맞는 1:1 상담을 요청합니다."]}, {"id": "g1770421552", "label": "8. 상담 가능하신 시간대를 남겨주세요. 예) 오전 11시-오후 2시사이", "required": true, "type": "text"}, {"id": "g1312865396", "label": "9. 다음 설명회로 원하시는 분야 및 내용을 남겨주세요.", "required": true, "type": "text"}, {"id": "g1991182704", "type": "info", "label": "참석해주신 모든 학부모님들께 감사드리며, 한 분 한 분의 정성스런 후기, 소중한 의견과 평가는 저희가 더 나은 교육서비스를 제공하는 데 큰 도움이 됩니다. 저희 리딩브레인영어학원은 우리 학생들에게 최상위1%의 교육을 경험시키고 꿈을 현실로 이루는 교육에 최선을 다하겠습니다.\n감사합니다:)"}]}], "once": true}$seed$::jsonb, 'closed', 200),
  ('sat-harvard-camp', $seed${"id": "sat-harvard-camp", "kicker": "Harvard Camps (with S.N.U) 설명회 만족도 조사", "title": "Harvard Camps (with S.N.U) 설명회 만족도 조사", "greeting": "Dear parents,", "intro": ["선착순 20명! 10/16(월)까지 계약금 50만원 납부 시, 할인가 적용 (10/20까지 완납조건 - 항공료 결제관련)"], "thanks": "소중한 응답 감사합니다. 리딩브레인영어학원", "sections": [{"title": "설문", "items": [{"id": "g1854072516", "type": "info", "label": "2024 리딩브레인 영어학원 윈터캠프 프로그램\nHarvard Camp 하버드대학캠프 (with S.N.U) \n\n《하버드대학에서 석.박사 교수님들과 함께하는 STEM프로그램!》\n\n●세계최고 대학캠프를 광명 리딩브레인 영어학원에서 시작합니다.\n●최고를 경험하는 이가 최고가 될 수 있습니다.\n●진짜교육은 경험을 사는 것입니다.\n\n필독! 👀👀선착순 20명! 10/16(월)까지 계약금 50만원 납부 시, \n할인가 적용 (10/20까지 완납조건 - 항공료 결제관련)👀👀\n\n📍D.CAMPS at SNU\n✅일정: [1차] 2024. 01. 08(월) - 12(금), \n              [2차] 2024. 01. 15(월) - 19(금) 중 택1\n✅대상: 현 초3-초6\n✅프로그램\n✔ Interstellar : Astronaut \n✔ Medical Science : So You Want to be a Doctor?\n✔ Explosive Creativity : Discover, Discern, Design \n✔ Artificial Intelligence : Deep Thoughts, Challenging Decisions \n\n\n📍D.CAMPS at Harvard ED-Tour\n✅일정: 2024. 01. 22(월) - 02. 06(화)\n✅프로그램\n✔ 하버드 STEM 프로그램\n✔ Ruters / Princeton STEM Seminar\n✔ Brown / RISD Study & Tour* or UMass Virtual Reality Seminar*\n*별표는 현재 학원팀을 위해 준비/진행중인 프로그램입니다\n✔ 보스턴 대학 방문 및 투어\n✔ 하버드 대학 / 예일 대학 투어\n✔ MIT 대학 / 브라운 대학 투어\n✔ 펜실베니아 대학 / 콜럼비아 대학 투어\n✔ 워싱턴 / 뉴욕 / 보스턴 투어", "image": "/img/gforms/sat-harvard-camp-1854072516.jpg"}, {"id": "g1281056010", "type": "info", "label": "", "image": "/img/gforms/sat-harvard-camp-1281056010.jpg"}, {"id": "g1313973280", "label": "[개인정보 수집.이용 동의]\n\n1. 수집하는 개인정보 항목 성명, 학년, 휴대폰번호 \n2. 개인정보의 수집 및 이용 목적 제공하신 정보는 학원 설명회 만족도 및 홍보를 위해 사용합니다. \n\n* 본인 확인 식별(동명이인 등)절차에 이용(성명, 학년, 휴대폰번호)\n* 의사소통 및 정보 전달, 홍보, 설명회 특전 전달 등에 이용(성명, 학년, 휴대폰번호)\n*개인정보의 보유 및 이용기간 수집된 개인정보의 보유 기간은 <만족도조사> 종료 후 1년간이며, 삭제 요청시, 당사자는 개인 정보를 재생이 불가능한 방법으로 즉시 파기합니다.", "required": true, "type": "single", "options": ["동의합니다.", "동의하지 않습니다."]}, {"id": "g1729183784", "label": "1. 학생이름을 기입해 주세요. \n예시) 김광명", "required": true, "type": "text", "short": true}, {"id": "g1093123497", "label": "2. 학생의 학교 및 학년을 기입해 주세요. (학교 / 학년)\n예시) 빛가온중 / 2학년", "required": true, "type": "text", "short": true}, {"id": "g1362273923", "label": "3. 학부모님 연락처를 알려주세요.", "required": true, "type": "text", "short": true}, {"id": "g1661186217", "label": "4. 하버드캠프 설명회 만족도를 체크해주세요:)", "required": true, "type": "single", "options": ["매우만족", "만족", "보통", "부족", "매우부족"]}, {"id": "g2117873659", "label": "5. 관심있으신 캠프유형을 선택해주세요.", "required": true, "type": "single", "options": ["서울대+하버드(아이비리그포함)캠프", "하버드(아이비리그포함)캠프"]}, {"id": "g536248050", "label": "6.  하버드해외캠프 설명회를 들으신 후, 더욱 궁금하신 내용이 있으시면 주저없이 남겨주세요.", "required": false, "type": "text"}, {"id": "g1810514794", "label": "7. 하버드해외캠프 설명회를 들으시고 궁금하신 부분이나 캠프신청에 관해 상담 여부를 체크해주세요.", "required": true, "type": "single", "options": ["상담필요", "상담불필요", "기타"]}, {"id": "g2035202840", "label": "8. 캠프관련하여 전화상담 가능하신 시간 남겨주세요. (ex 이번주 토요일 오전11시-오후2시)", "required": false, "type": "text"}, {"id": "g1604075135", "label": "9. 우리 학생의 하버드해외캠프 신청여부를 알려주세요.\n(추가 계약서 작성과 신청서 전달예정 / 10/16(월) 계약금50만원 마감 - 할인가제공)", "required": true, "type": "single", "options": ["신청확정예정", "신청예정(가족들과 상의 후, 결정)", "신청을 안할예정"]}, {"id": "g476198134", "label": "10. 캠프를 보내기 위한 단기 영어실력증진 프로그램이 필요하다고 생각하십니까?", "required": true, "type": "single", "options": ["네", "아니오"]}, {"id": "g1944735084", "label": "11. 해외캠프를 위한 혹은 영어수업프로그램으로 필요하신 것은 무엇일까요?", "required": true, "type": "single", "options": ["리스닝특화수업", "스피킹특화수업", "리딩특화수업", "잘모르겠다. 테스트와 상담을 받고 싶다."]}, {"id": "g627452911", "label": "12. 설명회 내용 중에서 우리 자녀에게 도움이 되었던 내용은 무엇일까요?", "required": true, "type": "text"}, {"id": "g635672531", "label": "13. 저희 리딩브레인 영어학원에 바라는 점이 있다면 남겨주세요. 적극적으로 반영하겠습니다.", "required": true, "type": "text"}, {"id": "g1134099060", "label": "14. 다음 캠프나 설명회로 원하시는 내용을 적어주세요.", "required": true, "type": "text"}, {"id": "g1794335123", "type": "info", "label": "하버드 해외캠프에 관심을 가지고 참석해주셔셔 감사드립니다. 우리 아이들에게 시야를 넓혀주는 올바른 영어교육으로 보답드리겠습니다.\n설문조사에 적극적으로 참여해주신 5분에게, \n스타벅스 키프티콘을 드립니다. \n감사합니다:)", "image": "/img/gforms/sat-harvard-camp-1794335123.jpg"}]}], "once": true}$seed$::jsonb, 'closed', 201),
